window.DATA = {"passages": [{"id": "01-pride-and-prejudice-ch1-2", "title": "Pride and Prejudice, Chapters 1-2 - Jane Austen", "lines": [{"id": 0, "para": 0, "quote": false, "text": "It is a truth universally acknowledged, that a single man in possession of a good fortune must be in want of a wife."}, {"id": 1, "para": 1, "quote": false, "text": "However little known the feelings or views of such a man may be on his first entering a neighbourhood, this truth is so well fixed in the minds of the surrounding families, that he is considered as the rightful property of some one or other of their daughters."}, {"id": 2, "para": 2, "quote": true, "text": "“My dear Mr. Bennet,”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "excited", "intensity": "high"}, "wrong": false}, {"id": 3, "para": 2, "quote": false, "text": "said his lady to him one day,"}, {"id": 4, "para": 2, "quote": true, "text": "“have you heard that Netherfield Park is let at last?”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "surprised", "intensity": "medium"}, "wrong": false}, {"id": 5, "para": 3, "quote": false, "text": "Mr. Bennet replied that he had not."}, {"id": 6, "para": 4, "quote": true, "text": "“But it is,”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "disgusted", "intensity": "low"}, "wrong": false}, {"id": 7, "para": 4, "quote": false, "text": "returned she;"}, {"id": 8, "para": 4, "quote": true, "text": "“for Mrs. Long has just been here, and she told me all about it.”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "excited", "intensity": "high"}, "wrong": false}, {"id": 9, "para": 5, "quote": false, "text": "Mr. Bennet made no answer."}, {"id": 10, "para": 6, "quote": true, "text": "“Do not you want to know who has taken it?”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "anxious", "intensity": "medium"}, "wrong": false}, {"id": 11, "para": 6, "quote": false, "text": "cried his wife, impatiently."}, {"id": 12, "para": 7, "quote": true, "text": "“_You_ want to tell me, and I have no objection to hearing it.”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "amused", "intensity": "low"}, "wrong": false}, {"id": 13, "para": 8, "quote": false, "text": "This was invitation enough."}, {"id": 14, "para": 9, "quote": true, "text": "“Why, my dear, you must know, Mrs. Long says that Netherfield is taken by a young man of large fortune from the north of England; that he came down on Monday in a chaise and four to see the place, and was so much delighted with it that he agreed with Mr. Morris immediately; that he is to take possession before Michaelmas, and some of his servants are to be in the house by the end of next week.”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "excited", "intensity": "high"}, "wrong": false}, {"id": 15, "para": 10, "quote": true, "text": "“What is his name?”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 16, "para": 11, "quote": true, "text": "“Bingley.”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 17, "para": 12, "quote": true, "text": "“Is he married or single?”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 18, "para": 13, "quote": true, "text": "“Oh, single, my dear, to be sure! A single man of large fortune; four or five thousand a year. What a fine thing for our girls!”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "excited", "intensity": "high"}, "wrong": false}, {"id": 19, "para": 14, "quote": true, "text": "“How so? how can it affect them?”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 20, "para": 15, "quote": true, "text": "“My dear Mr. Bennet,”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "excited", "intensity": "high"}, "wrong": false}, {"id": 21, "para": 15, "quote": false, "text": "replied his wife,"}, {"id": 22, "para": 15, "quote": true, "text": "“how can you be so tiresome? You must know that I am thinking of his marrying one of them.”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "excited", "intensity": "high"}, "wrong": false}, {"id": 23, "para": 16, "quote": true, "text": "“Is that his design in settling here?”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 24, "para": 17, "quote": true, "text": "“Design? Nonsense, how can you talk so! But it is very likely that he _may_ fall in love with one of them, and therefore you must visit him as soon as he comes.”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "excited", "intensity": "high"}, "wrong": false}, {"id": 25, "para": 18, "quote": true, "text": "“I see no occasion for that. You and the girls may go--or you may send them by themselves, which perhaps will be still better; for as you are as handsome as any of them, Mr. Bingley might like you the best of the party.”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "sad", "intensity": "low"}, "wrong": false}, {"id": 26, "para": 19, "quote": true, "text": "“My dear, you flatter me. I certainly _have_ had my share of beauty, but I do not pretend to be anything extraordinary now. When a woman has five grown-up daughters, she ought to give over thinking of her own beauty.”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 27, "para": 20, "quote": true, "text": "“In such cases, a woman has not often much beauty to think of.”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 28, "para": 21, "quote": true, "text": "“But, my dear, you must indeed go and see Mr. Bingley when he comes into the neighbourhood.”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "excited", "intensity": "high"}, "wrong": false}, {"id": 29, "para": 22, "quote": true, "text": "“It is more than I engage for, I assure you.”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 30, "para": 23, "quote": true, "text": "“But consider your daughters. Only think what an establishment it would be for one of them. Sir William and Lady Lucas are determined to go, merely on that account; for in general, you know, they visit no new comers. Indeed you must go, for it will be impossible for _us_ to visit him, if you do not.”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "excited", "intensity": "high"}, "wrong": false}, {"id": 31, "para": 24, "quote": true, "text": "“You are over scrupulous, surely. I dare say Mr. Bingley will be very glad to see you; and I will send a few lines by you to assure him of my hearty consent to his marrying whichever he chooses of the girls--though I must throw in a good word for my little Lizzy.”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "excited", "intensity": "high"}, "wrong": true}, {"id": 32, "para": 25, "quote": true, "text": "“I desire you will do no such thing. Lizzy is not a bit better than the others: and I am sure she is not half so handsome as Jane, nor half so good-humoured as Lydia. But you are always giving _her_ the preference.”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": true}, {"id": 33, "para": 26, "quote": true, "text": "“They have none of them much to recommend them,”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 34, "para": 26, "quote": false, "text": "replied he:"}, {"id": 35, "para": 26, "quote": true, "text": "“they are all silly and ignorant like other girls; but Lizzy has something more of quickness than her sisters.”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 36, "para": 27, "quote": true, "text": "“Mr. Bennet, how can you abuse your own children in such a way? You take delight in vexing me. You have no compassion on my poor nerves.”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "anxious", "intensity": "high"}, "wrong": false}, {"id": 37, "para": 28, "quote": true, "text": "“You mistake me, my dear. I have a high respect for your nerves. They are my old friends. I have heard you mention them with consideration these twenty years at least.”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 38, "para": 29, "quote": true, "text": "“Ah, you do not know what I suffer.”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "anxious", "intensity": "high"}, "wrong": false}, {"id": 39, "para": 30, "quote": true, "text": "“But I hope you will get over it, and live to see many young men of four thousand a year come into the neighbourhood.”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 40, "para": 31, "quote": true, "text": "“It will be no use to us, if twenty such should come, since you will not visit them.”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 41, "para": 32, "quote": true, "text": "“Depend upon it, my dear, that when there are twenty, I will visit them all.”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": true}, {"id": 42, "para": 33, "quote": false, "text": "Mr. Bennet was so odd a mixture of quick parts, sarcastic humour, reserve, and caprice, that the experience of three-and-twenty years had been insufficient to make his wife understand his character. _Her_ mind was less difficult to develope. She was a woman of mean understanding, little information, and uncertain temper. When she was discontented, she fancied herself nervous. The business of her life was to get her daughters married: its solace was visiting and news."}, {"id": 43, "para": 34, "quote": false, "text": "CHAPTER II."}, {"id": 44, "para": 35, "quote": false, "text": "Mr. Bennet was among the earliest of those who waited on Mr. Bingley. He had always intended to visit him, though to the last always assuring his wife that he should not go; and till the evening after the visit was paid she had no knowledge of it. It was then disclosed in the following manner. Observing his second daughter employed in trimming a hat, he suddenly addressed her with,--"}, {"id": 45, "para": 36, "quote": true, "text": "“I hope Mr. Bingley will like it, Lizzy.”", "label": {"speaker": "Lizzy", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": true}, {"id": 46, "para": 37, "quote": true, "text": "“We are not in a way to know _what_ Mr. Bingley likes,”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "angry", "intensity": "medium"}, "wrong": false}, {"id": 47, "para": 37, "quote": false, "text": "said her mother, resentfully,"}, {"id": 48, "para": 37, "quote": true, "text": "“since we are not to visit.”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "angry", "intensity": "medium"}, "wrong": false}, {"id": 49, "para": 38, "quote": true, "text": "“But you forget, mamma,”", "label": {"speaker": "Lizzy", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 50, "para": 38, "quote": false, "text": "said Elizabeth,"}, {"id": 51, "para": 38, "quote": true, "text": "“that we shall meet him at the assemblies, and that Mrs. Long has promised to introduce him.”", "label": {"speaker": "Lizzy", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 52, "para": 39, "quote": true, "text": "“I do not believe Mrs. Long will do any such thing. She has two nieces of her own. She is a selfish, hypocritical woman, and I have no opinion of her.”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "disgusted", "intensity": "medium"}, "wrong": false}, {"id": 53, "para": 40, "quote": true, "text": "“No more have I,”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 54, "para": 40, "quote": false, "text": "said Mr. Bennet;"}, {"id": 55, "para": 40, "quote": true, "text": "“and I am glad to find that you do not depend on her serving you.”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 56, "para": 41, "quote": false, "text": "Mrs. Bennet deigned not to make any reply; but, unable to contain herself, began scolding one of her daughters."}, {"id": 57, "para": 42, "quote": true, "text": "“Don’t keep coughing so, Kitty, for heaven’s sake! Have a little compassion on my nerves. You tear them to pieces.”", "label": {"speaker": "Kitty", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": true}, {"id": 58, "para": 43, "quote": true, "text": "“Kitty has no discretion in her coughs,”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 59, "para": 43, "quote": false, "text": "said her father;"}, {"id": 60, "para": 43, "quote": true, "text": "“she times them ill.”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 61, "para": 44, "quote": true, "text": "“I do not cough for my own amusement,”", "label": {"speaker": "Kitty", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 62, "para": 44, "quote": false, "text": "replied Kitty, fretfully."}, {"id": 63, "para": 44, "quote": true, "text": "“When is your next ball to be, Lizzy?”", "label": {"speaker": "Kitty", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 64, "para": 45, "quote": true, "text": "“To-morrow fortnight.”", "label": {"speaker": "Lizzy", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 65, "para": 46, "quote": true, "text": "“Ay, so it is,”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 66, "para": 46, "quote": false, "text": "cried her mother,"}, {"id": 67, "para": 46, "quote": true, "text": "“and Mrs. Long does not come back till the day before; so, it will be impossible for her to introduce him, for she will not know him herself.”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 68, "para": 47, "quote": true, "text": "“Then, my dear, you may have the advantage of your friend, and introduce Mr. Bingley to _her_.”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 69, "para": 48, "quote": true, "text": "“Impossible, Mr. Bennet, impossible, when I am not acquainted with him myself; how can you be so teasing?”", "label": {"speaker": "Lizzy", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": true}, {"id": 70, "para": 49, "quote": true, "text": "“I honour your circumspection. A fortnight’s acquaintance is certainly very little. One cannot know what a man really is by the end of a fortnight. But if _we_ do not venture, somebody else will; and after all, Mrs. Long and her nieces must stand their chance; and, therefore, as she will think it an act of kindness, if you decline the office, I will take it on myself.”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 71, "para": 50, "quote": false, "text": "The girls stared at their father. Mrs. Bennet said only,"}, {"id": 72, "para": 50, "quote": true, "text": "“Nonsense, nonsense!”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 73, "para": 51, "quote": true, "text": "“What can be the meaning of that emphatic exclamation?”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 74, "para": 51, "quote": false, "text": "cried he."}, {"id": 75, "para": 51, "quote": true, "text": "“Do you consider the forms of introduction, and the stress that is laid on them, as nonsense? I cannot quite agree with you _there_. What say you, Mary? For you are a young lady of deep reflection, I know, and read great books, and make extracts.”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 76, "para": 52, "quote": false, "text": "Mary wished to say something very sensible, but knew not how."}, {"id": 77, "para": 53, "quote": true, "text": "“While Mary is adjusting her ideas,”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 78, "para": 53, "quote": false, "text": "he continued,"}, {"id": 79, "para": 53, "quote": true, "text": "“let us return to Mr. Bingley.”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 80, "para": 54, "quote": true, "text": "“I am sick of Mr. Bingley,”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 81, "para": 54, "quote": false, "text": "cried his wife."}, {"id": 82, "para": 55, "quote": true, "text": "“I am sorry to hear _that_; but why did you not tell me so before? If I had known as much this morning, I certainly would not have called on him. It is very unlucky; but as I have actually paid the visit, we cannot escape the acquaintance now.”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 83, "para": 56, "quote": false, "text": "The astonishment of the ladies was just what he wished--that of Mrs. Bennet perhaps surpassing the rest; though when the first tumult of joy was over, she began to declare that it was what she had expected all the while."}, {"id": 84, "para": 57, "quote": true, "text": "“How good it was in you, my dear Mr. Bennet! But I knew I should persuade you at last. I was sure you loved your girls too well to neglect such an acquaintance. Well, how pleased I am! And it is such a good joke, too, that you should have gone this morning, and never said a word about it till now.”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "happy", "intensity": "high"}, "wrong": false}, {"id": 85, "para": 58, "quote": true, "text": "“Now, Kitty, you may cough as much as you choose,”", "label": {"speaker": "Mr. Bennet", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 86, "para": 58, "quote": false, "text": "said Mr. Bennet; and, as he spoke, he left the room, fatigued with the raptures of his wife."}, {"id": 87, "para": 59, "quote": true, "text": "“What an excellent father you have, girls,”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "happy", "intensity": "medium"}, "wrong": false}, {"id": 88, "para": 59, "quote": false, "text": "said she, when the door was shut."}, {"id": 89, "para": 59, "quote": true, "text": "“I do not know how you will ever make him amends for his kindness; or me either, for that matter. At our time of life, it is not so pleasant, I can tell you, to be making new acquaintances every day; but for your sakes we would do anything. Lydia, my love, though you _are_ the youngest, I dare say Mr. Bingley will dance with you at the next ball.”", "label": {"speaker": "Mrs. Bennet", "kind": "speech", "emotion": "happy", "intensity": "medium"}, "wrong": false}, {"id": 90, "para": 60, "quote": true, "text": "“Oh,”", "label": {"speaker": "Lydia", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 91, "para": 60, "quote": false, "text": "said Lydia, stoutly,"}, {"id": 92, "para": 60, "quote": true, "text": "“I am not afraid; for though I _am_ the youngest, I’m the tallest.”", "label": {"speaker": "Lydia", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 93, "para": 61, "quote": false, "text": "The rest of the evening was spent in conjecturing how soon he would return Mr. Bennet’s visit, and determining when they should ask him to dinner."}], "narrator": {"person": "third", "character": ""}, "characters": [{"name": "Mr. Bennet", "aliases": ["Mr. Bennet", "my dear Mr. Bennet", "you", "he", "your husband", "Mr. Bennet", "you", "he"], "gender": "male", "age": "adult"}, {"name": "Mrs. Bennet", "aliases": ["his lady", "Mrs. Bennet", "his wife", "my dear", "you", "she", "her", "Mrs. Bennet"], "gender": "female", "age": "adult"}, {"name": "Mrs. Long", "aliases": ["Mrs. Long", "she", "a selfish, hypocritical woman"], "gender": "female", "age": "adult"}, {"name": "Mr. Morris", "aliases": ["Mr. Morris", "he"], "gender": "male", "age": "adult"}, {"name": "Mr. Bingley", "aliases": ["Mr. Bingley", "a young man", "he", "Mr. Bingley", "him", "Mr. Bingley", "you"], "gender": "male", "age": "adult"}, {"name": "Sir William", "aliases": ["Sir William", "he"], "gender": "male", "age": "adult"}, {"name": "Lady Lucas", "aliases": ["Lady Lucas", "she"], "gender": "female", "age": "adult"}, {"name": "Lizzy", "aliases": ["Lizzy", "my little Lizzy", "Lizzy", "her", "she", "Lizzy", "her"], "gender": "female", "age": "young adult"}, {"name": "Jane", "aliases": ["Jane", "one of them", "she", "her", "Jane", "her"], "gender": "female", "age": "young adult"}, {"name": "Lydia", "aliases": ["Lydia", "one of them", "she", "her", "Lydia", "her"], "gender": "female", "age": "young adult"}, {"name": "Kitty", "aliases": ["Kitty", "one of them", "she", "her", "Kitty", "her"], "gender": "female", "age": "young adult"}, {"name": "Mary", "aliases": ["Mary", "one of them", "she", "her", "Mary", "her"], "gender": "female", "age": "young adult"}], "scenes": [{"first_paragraph": 1, "setting": "The Bennet drawing-room", "mood": "calm"}, {"first_paragraph": 35, "setting": "The Bennet drawing-room", "mood": "tense"}]}, {"id": "02-alice-mad-tea-party", "title": "Alice's Adventures in Wonderland, Chapter VII: A Mad Tea-Party - Lewis Carroll", "lines": [{"id": 0, "para": 0, "quote": false, "text": "There was a table set out under a tree in front of the house, and the March Hare and the Hatter were having tea at it: a Dormouse was sitting between them, fast asleep, and the other two were using it as a cushion, resting their elbows on it, and talking over its head."}, {"id": 1, "para": 0, "quote": true, "text": "“Very uncomfortable for the Dormouse,”", "label": {"speaker": "Narrator", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": true}, {"id": 2, "para": 0, "quote": false, "text": "thought Alice;"}, {"id": 3, "para": 0, "quote": true, "text": "“only, as it’s asleep, I suppose it doesn’t mind.”", "label": {"speaker": "Alice", "kind": "thought", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 4, "para": 1, "quote": false, "text": "The table was a large one, but the three were all crowded together at one corner of it:"}, {"id": 5, "para": 1, "quote": true, "text": "“No room! No room!”", "label": {"speaker": "Narrator", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": true}, {"id": 6, "para": 1, "quote": false, "text": "they cried out when they saw Alice coming."}, {"id": 7, "para": 1, "quote": true, "text": "“There’s _plenty_ of room!”", "label": {"speaker": "March Hare", "kind": "speech", "emotion": "surprised", "intensity": "high"}, "wrong": true}, {"id": 8, "para": 1, "quote": false, "text": "said Alice indignantly, and she sat down in a large arm-chair at one end of the table."}, {"id": 9, "para": 2, "quote": true, "text": "“Have some wine,”", "label": {"speaker": "March Hare", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 10, "para": 2, "quote": false, "text": "the March Hare said in an encouraging tone."}, {"id": 11, "para": 3, "quote": false, "text": "Alice looked all round the table, but there was nothing on it but tea."}, {"id": 12, "para": 3, "quote": true, "text": "“I don’t see any wine,”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 13, "para": 3, "quote": false, "text": "she remarked."}, {"id": 14, "para": 4, "quote": true, "text": "“There isn’t any,”", "label": {"speaker": "March Hare", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 15, "para": 4, "quote": false, "text": "said the March Hare."}, {"id": 16, "para": 5, "quote": true, "text": "“Then it wasn’t very civil of you to offer it,”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "angry", "intensity": "medium"}, "wrong": false}, {"id": 17, "para": 5, "quote": false, "text": "said Alice angrily."}, {"id": 18, "para": 6, "quote": true, "text": "“It wasn’t very civil of you to sit down without being invited,”", "label": {"speaker": "March Hare", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 19, "para": 6, "quote": false, "text": "said the March Hare."}, {"id": 20, "para": 7, "quote": true, "text": "“I didn’t know it was _your_ table,”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 21, "para": 7, "quote": false, "text": "said Alice;"}, {"id": 22, "para": 7, "quote": true, "text": "“it’s laid for a great many more than three.”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 23, "para": 8, "quote": true, "text": "“Your hair wants cutting,”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 24, "para": 8, "quote": false, "text": "said the Hatter. He had been looking at Alice for some time with great curiosity, and this was his first speech."}, {"id": 25, "para": 9, "quote": true, "text": "“You should learn not to make personal remarks,”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "neutral", "intensity": "medium"}, "wrong": false}, {"id": 26, "para": 9, "quote": false, "text": "Alice said with some severity;"}, {"id": 27, "para": 9, "quote": true, "text": "“it’s very rude.”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 28, "para": 10, "quote": false, "text": "The Hatter opened his eyes very wide on hearing this; but all he _said_ was,"}, {"id": 29, "para": 10, "quote": true, "text": "“Why is a raven like a writing-desk?”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 30, "para": 11, "quote": true, "text": "“Come, we shall have some fun now!”", "label": {"speaker": "Alice", "kind": "thought", "emotion": "happy", "intensity": "low"}, "wrong": false}, {"id": 31, "para": 11, "quote": false, "text": "thought Alice."}, {"id": 32, "para": 11, "quote": true, "text": "“I’m glad they’ve begun asking riddles.—I believe I can guess that,”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 33, "para": 11, "quote": false, "text": "she added aloud."}, {"id": 34, "para": 12, "quote": true, "text": "“Do you mean that you think you can find out the answer to it?”", "label": {"speaker": "March Hare", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 35, "para": 12, "quote": false, "text": "said the March Hare."}, {"id": 36, "para": 13, "quote": true, "text": "“Exactly so,”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 37, "para": 13, "quote": false, "text": "said Alice."}, {"id": 38, "para": 14, "quote": true, "text": "“Then you should say what you mean,”", "label": {"speaker": "March Hare", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 39, "para": 14, "quote": false, "text": "the March Hare went on."}, {"id": 40, "para": 15, "quote": true, "text": "“I do,”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 41, "para": 15, "quote": false, "text": "Alice hastily replied;"}, {"id": 42, "para": 15, "quote": true, "text": "“at least—at least I mean what I say—that’s the same thing, you know.”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 43, "para": 16, "quote": true, "text": "“Not the same thing a bit!”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 44, "para": 16, "quote": false, "text": "said the Hatter."}, {"id": 45, "para": 16, "quote": true, "text": "“You might just as well say that ‘I see what I eat’ is the same thing as ‘I eat what I see’!”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 46, "para": 17, "quote": true, "text": "“You might just as well say,”", "label": {"speaker": "March Hare", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 47, "para": 17, "quote": false, "text": "added the March Hare,"}, {"id": 48, "para": 17, "quote": true, "text": "“that ‘I like what I get’ is the same thing as ‘I get what I like’!”", "label": {"speaker": "March Hare", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 49, "para": 18, "quote": true, "text": "“You might just as well say,”", "label": {"speaker": "Dormouse", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 50, "para": 18, "quote": false, "text": "added the Dormouse, who seemed to be talking in his sleep,"}, {"id": 51, "para": 18, "quote": true, "text": "“that ‘I breathe when I sleep’ is the same thing as ‘I sleep when I breathe’!”", "label": {"speaker": "Dormouse", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 52, "para": 19, "quote": true, "text": "“It _is_ the same thing with you,”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 53, "para": 19, "quote": false, "text": "said the Hatter, and here the conversation dropped, and the party sat silent for a minute, while Alice thought over all she could remember about ravens and writing-desks, which wasn’t much."}, {"id": 54, "para": 20, "quote": false, "text": "The Hatter was the first to break the silence."}, {"id": 55, "para": 20, "quote": true, "text": "“What day of the month is it?”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 56, "para": 20, "quote": false, "text": "he said, turning to Alice: he had taken his watch out of his pocket, and was looking at it uneasily, shaking it every now and then, and holding it to his ear."}, {"id": 57, "para": 21, "quote": false, "text": "Alice considered a little, and then said"}, {"id": 58, "para": 21, "quote": true, "text": "“The fourth.”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 59, "para": 22, "quote": true, "text": "“Two days wrong!”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "sad", "intensity": "medium"}, "wrong": false}, {"id": 60, "para": 22, "quote": false, "text": "sighed the Hatter."}, {"id": 61, "para": 22, "quote": true, "text": "“I told you butter wouldn’t suit the works!”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "angry", "intensity": "medium"}, "wrong": false}, {"id": 62, "para": 22, "quote": false, "text": "he added looking angrily at the March Hare."}, {"id": 63, "para": 23, "quote": true, "text": "“It was the _best_ butter,”", "label": {"speaker": "March Hare", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 64, "para": 23, "quote": false, "text": "the March Hare meekly replied."}, {"id": 65, "para": 24, "quote": true, "text": "“Yes, but some crumbs must have got in as well,”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 66, "para": 24, "quote": false, "text": "the Hatter grumbled:"}, {"id": 67, "para": 24, "quote": true, "text": "“you shouldn’t have put it in with the bread-knife.”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 68, "para": 25, "quote": false, "text": "The March Hare took the watch and looked at it gloomily: then he dipped it into his cup of tea, and looked at it again: but he could think of nothing better to say than his first remark,"}, {"id": 69, "para": 25, "quote": true, "text": "“It was the _best_ butter, you know.”", "label": {"speaker": "March Hare", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 70, "para": 26, "quote": false, "text": "Alice had been looking over his shoulder with some curiosity."}, {"id": 71, "para": 26, "quote": true, "text": "“What a funny watch!”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 72, "para": 26, "quote": false, "text": "she remarked."}, {"id": 73, "para": 26, "quote": true, "text": "“It tells the day of the month, and doesn’t tell what o’clock it is!”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 74, "para": 27, "quote": true, "text": "“Why should it?”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 75, "para": 27, "quote": false, "text": "muttered the Hatter."}, {"id": 76, "para": 27, "quote": true, "text": "“Does _your_ watch tell you what year it is?”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 77, "para": 28, "quote": true, "text": "“Of course not,”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 78, "para": 28, "quote": false, "text": "Alice replied very readily:"}, {"id": 79, "para": 28, "quote": true, "text": "“but that’s because it stays the same year for such a long time together.”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 80, "para": 29, "quote": true, "text": "“Which is just the case with _mine_,”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 81, "para": 29, "quote": false, "text": "said the Hatter."}, {"id": 82, "para": 30, "quote": false, "text": "Alice felt dreadfully puzzled, The Hatter’s remark seemed to have no sort of meaning in it, and yet it was certainly English."}, {"id": 83, "para": 30, "quote": true, "text": "“I don’t quite understand you,”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 84, "para": 30, "quote": false, "text": "she said, as politely as she could."}, {"id": 85, "para": 31, "quote": true, "text": "“The Dormouse is asleep again,”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 86, "para": 31, "quote": false, "text": "said the Hatter, and he poured a little hot tea upon its nose."}, {"id": 87, "para": 32, "quote": false, "text": "The Dormouse shook its head impatiently, and said, without opening its eyes,"}, {"id": 88, "para": 32, "quote": true, "text": "“Of course, of course; just what I was going to remark myself.”", "label": {"speaker": "Dormouse", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 89, "para": 33, "quote": true, "text": "“Have you guessed the riddle yet?”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 90, "para": 33, "quote": false, "text": "the Hatter said, turning to Alice again."}, {"id": 91, "para": 34, "quote": true, "text": "“No, I give it up,”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 92, "para": 34, "quote": false, "text": "Alice replied:"}, {"id": 93, "para": 34, "quote": true, "text": "“what’s the answer?”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 94, "para": 35, "quote": true, "text": "“I haven’t the slightest idea,”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 95, "para": 35, "quote": false, "text": "said the Hatter."}, {"id": 96, "para": 36, "quote": true, "text": "“Nor I,”", "label": {"speaker": "March Hare", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 97, "para": 36, "quote": false, "text": "said the March Hare."}, {"id": 98, "para": 37, "quote": false, "text": "Alice sighed wearily."}, {"id": 99, "para": 37, "quote": true, "text": "“I think you might do something better with the time,”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 100, "para": 37, "quote": false, "text": "she said,"}, {"id": 101, "para": 37, "quote": true, "text": "“than waste it in asking riddles that have no answers.”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 102, "para": 38, "quote": true, "text": "“If you knew Time as well as I do,”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 103, "para": 38, "quote": false, "text": "said the Hatter,"}, {"id": 104, "para": 38, "quote": true, "text": "“you wouldn’t talk about wasting _it_. It’s _him_.”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 105, "para": 39, "quote": true, "text": "“I don’t know what you mean,”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 106, "para": 39, "quote": false, "text": "said Alice."}, {"id": 107, "para": 40, "quote": true, "text": "“Of course you don’t!”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 108, "para": 40, "quote": false, "text": "the Hatter said, tossing his head contemptuously."}, {"id": 109, "para": 40, "quote": true, "text": "“I dare say you never even spoke to Time!”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 110, "para": 41, "quote": true, "text": "“Perhaps not,”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 111, "para": 41, "quote": false, "text": "Alice cautiously replied:"}, {"id": 112, "para": 41, "quote": true, "text": "“but I know I have to beat time when I learn music.”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "disgusted", "intensity": "low"}, "wrong": false}, {"id": 113, "para": 42, "quote": true, "text": "“Ah! that accounts for it,”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "amused", "intensity": "medium"}, "wrong": false}, {"id": 114, "para": 42, "quote": false, "text": "said the Hatter."}, {"id": 115, "para": 42, "quote": true, "text": "“He won’t stand beating. Now, if you only kept on good terms with him, he’d do almost anything you liked with the clock. For instance, suppose it were nine o’clock in the morning, just time to begin lessons: you’d only have to whisper a hint to Time, and round goes the clock in a twinkling! Half-past one, time for dinner!”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 116, "para": 43, "quote": false, "text": "("}, {"id": 117, "para": 43, "quote": true, "text": "“I only wish it was,”", "label": {"speaker": "March Hare", "kind": "thought", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 118, "para": 43, "quote": false, "text": "the March Hare said to itself in a whisper.)"}, {"id": 119, "para": 44, "quote": true, "text": "“That would be grand, certainly,”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "amused", "intensity": "low"}, "wrong": false}, {"id": 120, "para": 44, "quote": false, "text": "said Alice thoughtfully:"}, {"id": 121, "para": 44, "quote": true, "text": "“but then—I shouldn’t be hungry for it, you know.”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 122, "para": 45, "quote": true, "text": "“Not at first, perhaps,”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "amused", "intensity": "low"}, "wrong": false}, {"id": 123, "para": 45, "quote": false, "text": "said the Hatter:"}, {"id": 124, "para": 45, "quote": true, "text": "“but you could keep it to half-past one as long as you liked.”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 125, "para": 46, "quote": true, "text": "“Is that the way _you_ manage?”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 126, "para": 46, "quote": false, "text": "Alice asked."}, {"id": 127, "para": 47, "quote": false, "text": "The Hatter shook his head mournfully."}, {"id": 128, "para": 47, "quote": true, "text": "“Not I!”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "sad", "intensity": "medium"}, "wrong": false}, {"id": 129, "para": 47, "quote": false, "text": "he replied."}, {"id": 130, "para": 47, "quote": true, "text": "“We quarrelled last March—just before _he_ went mad, you know—”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "sad", "intensity": "medium"}, "wrong": false}, {"id": 131, "para": 47, "quote": false, "text": "(pointing with his tea spoon at the March Hare,)"}, {"id": 132, "para": 47, "quote": true, "text": "“—it was at the great concert given by the Queen of Hearts, and I had to sing", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "sad", "intensity": "medium"}, "wrong": false}, {"id": 133, "para": 48, "quote": false, "text": "‘Twinkle, twinkle, little bat! How I wonder what you’re at!’"}, {"id": 134, "para": 49, "quote": false, "text": "You know the song, perhaps?”"}, {"id": 135, "para": 50, "quote": true, "text": "“I’ve heard something like it,”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 136, "para": 50, "quote": false, "text": "said Alice."}, {"id": 137, "para": 51, "quote": true, "text": "“It goes on, you know,”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 138, "para": 51, "quote": false, "text": "the Hatter continued,"}, {"id": 139, "para": 51, "quote": true, "text": "“in this way:—", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 140, "para": 52, "quote": false, "text": "‘Up above the world you fly, Like a tea-tray in the sky. Twinkle, twinkle—’”"}, {"id": 141, "para": 53, "quote": false, "text": "Here the Dormouse shook itself, and began singing in its sleep"}, {"id": 142, "para": 53, "quote": true, "text": "“_Twinkle, twinkle, twinkle, twinkle_—”", "label": {"speaker": "Dormouse", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 143, "para": 53, "quote": false, "text": "and went on so long that they had to pinch it to make it stop."}, {"id": 144, "para": 54, "quote": true, "text": "“Well, I’d hardly finished the first verse,”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "sad", "intensity": "medium"}, "wrong": false}, {"id": 145, "para": 54, "quote": false, "text": "said the Hatter,"}, {"id": 146, "para": 54, "quote": true, "text": "“when the Queen jumped up and bawled out, ‘He’s murdering the time! Off with his head!’”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "sad", "intensity": "medium"}, "wrong": false}, {"id": 147, "para": 55, "quote": true, "text": "“How dreadfully savage!”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 148, "para": 55, "quote": false, "text": "exclaimed Alice."}, {"id": 149, "para": 56, "quote": true, "text": "“And ever since that,”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "sad", "intensity": "medium"}, "wrong": false}, {"id": 150, "para": 56, "quote": false, "text": "the Hatter went on in a mournful tone,"}, {"id": 151, "para": 56, "quote": true, "text": "“he won’t do a thing I ask! It’s always six o’clock now.”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "sad", "intensity": "medium"}, "wrong": false}, {"id": 152, "para": 57, "quote": false, "text": "A bright idea came into Alice’s head."}, {"id": 153, "para": 57, "quote": true, "text": "“Is that the reason so many tea-things are put out here?”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 154, "para": 57, "quote": false, "text": "she asked."}, {"id": 155, "para": 58, "quote": true, "text": "“Yes, that’s it,”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "sad", "intensity": "medium"}, "wrong": false}, {"id": 156, "para": 58, "quote": false, "text": "said the Hatter with a sigh:"}, {"id": 157, "para": 58, "quote": true, "text": "“it’s always tea-time, and we’ve no time to wash the things between whiles.”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "sad", "intensity": "medium"}, "wrong": false}, {"id": 158, "para": 59, "quote": true, "text": "“Then you keep moving round, I suppose?”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 159, "para": 59, "quote": false, "text": "said Alice."}, {"id": 160, "para": 60, "quote": true, "text": "“Exactly so,”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 161, "para": 60, "quote": false, "text": "said the Hatter:"}, {"id": 162, "para": 60, "quote": true, "text": "“as the things get used up.”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 163, "para": 61, "quote": true, "text": "“But what happens when you come to the beginning again?”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 164, "para": 61, "quote": false, "text": "Alice ventured to ask."}, {"id": 165, "para": 62, "quote": true, "text": "“Suppose we change the subject,”", "label": {"speaker": "March Hare", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 166, "para": 62, "quote": false, "text": "the March Hare interrupted, yawning."}, {"id": 167, "para": 62, "quote": true, "text": "“I’m getting tired of this. I vote the young lady tells us a story.”", "label": {"speaker": "March Hare", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 168, "para": 63, "quote": true, "text": "“I’m afraid I don’t know one,”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 169, "para": 63, "quote": false, "text": "said Alice, rather alarmed at the proposal."}, {"id": 170, "para": 64, "quote": true, "text": "“Then the Dormouse shall!”", "label": {"speaker": "March Hare", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 171, "para": 64, "quote": false, "text": "they both cried."}, {"id": 172, "para": 64, "quote": true, "text": "“Wake up, Dormouse!”", "label": {"speaker": "March Hare", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 173, "para": 64, "quote": false, "text": "And they pinched it on both sides at once."}, {"id": 174, "para": 65, "quote": false, "text": "The Dormouse slowly opened his eyes."}, {"id": 175, "para": 65, "quote": true, "text": "“I wasn’t asleep,”", "label": {"speaker": "Dormouse", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 176, "para": 65, "quote": false, "text": "he said in a hoarse, feeble voice:"}, {"id": 177, "para": 65, "quote": true, "text": "“I heard every word you fellows were saying.”", "label": {"speaker": "Dormouse", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 178, "para": 66, "quote": true, "text": "“Tell us a story!”", "label": {"speaker": "March Hare", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 179, "para": 66, "quote": false, "text": "said the March Hare."}, {"id": 180, "para": 67, "quote": true, "text": "“Yes, please do!”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 181, "para": 67, "quote": false, "text": "pleaded Alice."}, {"id": 182, "para": 68, "quote": true, "text": "“And be quick about it,”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 183, "para": 68, "quote": false, "text": "added the Hatter,"}, {"id": 184, "para": 68, "quote": true, "text": "“or you’ll be asleep again before it’s done.”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 185, "para": 69, "quote": true, "text": "“Once upon a time there were three little sisters,”", "label": {"speaker": "Dormouse", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 186, "para": 69, "quote": false, "text": "the Dormouse began in a great hurry;"}, {"id": 187, "para": 69, "quote": true, "text": "“and their names were Elsie, Lacie, and Tillie; and they lived at the bottom of a well—”", "label": {"speaker": "Dormouse", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 188, "para": 70, "quote": true, "text": "“What did they live on?”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 189, "para": 70, "quote": false, "text": "said Alice, who always took a great interest in questions of eating and drinking."}, {"id": 190, "para": 71, "quote": true, "text": "“They lived on treacle,”", "label": {"speaker": "Dormouse", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 191, "para": 71, "quote": false, "text": "said the Dormouse, after thinking a minute or two."}, {"id": 192, "para": 72, "quote": true, "text": "“They couldn’t have done that, you know,”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 193, "para": 72, "quote": false, "text": "Alice gently remarked;"}, {"id": 194, "para": 72, "quote": true, "text": "“they’d have been ill.”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 195, "para": 73, "quote": true, "text": "“So they were,”", "label": {"speaker": "Dormouse", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 196, "para": 73, "quote": false, "text": "said the Dormouse;"}, {"id": 197, "para": 73, "quote": true, "text": "“_very_ ill.”", "label": {"speaker": "Dormouse", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 198, "para": 74, "quote": false, "text": "Alice tried to fancy to herself what such an extraordinary way of living would be like, but it puzzled her too much, so she went on:"}, {"id": 199, "para": 74, "quote": true, "text": "“But why did they live at the bottom of a well?”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 200, "para": 75, "quote": true, "text": "“Take some more tea,”", "label": {"speaker": "March Hare", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 201, "para": 75, "quote": false, "text": "the March Hare said to Alice, very earnestly."}, {"id": 202, "para": 76, "quote": true, "text": "“I’ve had nothing yet,”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 203, "para": 76, "quote": false, "text": "Alice replied in an offended tone,"}, {"id": 204, "para": 76, "quote": true, "text": "“so I can’t take more.”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 205, "para": 77, "quote": true, "text": "“You mean you can’t take _less_,”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 206, "para": 77, "quote": false, "text": "said the Hatter:"}, {"id": 207, "para": 77, "quote": true, "text": "“it’s very easy to take _more_ than nothing.”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 208, "para": 78, "quote": true, "text": "“Nobody asked _your_ opinion,”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 209, "para": 78, "quote": false, "text": "said Alice."}, {"id": 210, "para": 79, "quote": true, "text": "“Who’s making personal remarks now?”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 211, "para": 79, "quote": false, "text": "the Hatter asked triumphantly."}, {"id": 212, "para": 80, "quote": false, "text": "Alice did not quite know what to say to this: so she helped herself to some tea and bread-and-butter, and then turned to the Dormouse, and repeated her question."}, {"id": 213, "para": 80, "quote": true, "text": "“Why did they live at the bottom of a well?”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 214, "para": 81, "quote": false, "text": "The Dormouse again took a minute or two to think about it, and then said,"}, {"id": 215, "para": 81, "quote": true, "text": "“It was a treacle-well.”", "label": {"speaker": "Dormouse", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 216, "para": 82, "quote": true, "text": "“There’s no such thing!”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 217, "para": 82, "quote": false, "text": "Alice was beginning very angrily, but the Hatter and the March Hare went"}, {"id": 218, "para": 82, "quote": true, "text": "“Sh! sh!”", "label": {"speaker": "March Hare", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 219, "para": 82, "quote": false, "text": "and the Dormouse sulkily remarked,"}, {"id": 220, "para": 82, "quote": true, "text": "“If you can’t be civil, you’d better finish the story for yourself.”", "label": {"speaker": "Dormouse", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 221, "para": 83, "quote": true, "text": "“No, please go on!”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 222, "para": 83, "quote": false, "text": "Alice said very humbly;"}, {"id": 223, "para": 83, "quote": true, "text": "“I won’t interrupt again. I dare say there may be _one_.”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 224, "para": 84, "quote": true, "text": "“One, indeed!”", "label": {"speaker": "Dormouse", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 225, "para": 84, "quote": false, "text": "said the Dormouse indignantly. However, he consented to go on."}, {"id": 226, "para": 84, "quote": true, "text": "“And so these three little sisters—they were learning to draw, you know—”", "label": {"speaker": "Dormouse", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 227, "para": 85, "quote": true, "text": "“What did they draw?”", "label": {"speaker": "Alice", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 228, "para": 85, "quote": false, "text": "said Alice, quite forgetting her promise."}, {"id": 229, "para": 86, "quote": true, "text": "“Treacle,”", "label": {"speaker": "Dormouse", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 230, "para": 86, "quote": false, "text": "said the Dormouse, without considering at all this time."}, {"id": 231, "para": 87, "quote": true, "text": "“I want a clean cup,”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 232, "para": 87, "quote": false, "text": "interrupted the Hatter:"}, {"id": 233, "para": 87, "quote": true, "text": "“let’s all move one place on.”", "label": {"speaker": "Hatter", "kind": "speech", "emotion": "excited", "intensity": "medium"}, "wrong": false}, {"id": 234, "para": 88, "quote": false, "text": "He moved on as he spoke, and the Dormouse followed him: the March Hare moved into the Dormouse’s place, and Alice rather unwillingly took the place of the March Hare. The Hatter was the only one who got any advantage from the change: and Alice was a good deal worse off than before, as the March Hare had just upset the milk-jug into his plate."}], "narrator": {"person": "third", "character": ""}, "characters": [{"name": "Alice", "aliases": ["Alice"], "gender": "female", "age": "child"}, {"name": "March Hare", "aliases": ["the March Hare", "Hare"], "gender": "male", "age": "adult"}, {"name": "Hatter", "aliases": ["the Hatter", "Hatter"], "gender": "male", "age": "adult"}, {"name": "Dormouse", "aliases": ["the Dormouse", "Dormouse"], "gender": "male", "age": "child"}, {"name": "Queen of Hearts", "aliases": ["the Queen of Hearts"], "gender": "female", "age": "adult"}, {"name": "Time", "aliases": ["Time"], "gender": "male", "age": "adult"}, {"name": "Elsie", "aliases": ["Elsie"], "gender": "female", "age": "child"}, {"name": "Lacie", "aliases": ["Lacie"], "gender": "female", "age": "child"}, {"name": "Tillie", "aliases": ["Tillie"], "gender": "female", "age": "child"}], "scenes": [{"first_paragraph": 1, "setting": "Tea party under a tree", "mood": "anxious"}, {"first_paragraph": 21, "setting": "Tea party under a tree", "mood": "melancholic"}, {"first_paragraph": 65, "setting": "Tea party under a tree", "mood": "tense"}]}, {"id": "03-holmes-scandal-in-bohemia", "title": "The Adventures of Sherlock Holmes, A Scandal in Bohemia (opening) - Arthur Conan Doyle", "lines": [{"id": 0, "para": 0, "quote": false, "text": "To Sherlock Holmes she is always _the_ woman. I have seldom heard him mention her under any other name. In his eyes she eclipses and predominates the whole of her sex. It was not that he felt any emotion akin to love for Irene Adler. All emotions, and that one particularly, were abhorrent to his cold, precise but admirably balanced mind. He was, I take it, the most perfect reasoning and observing machine that the world has seen, but as a lover he would have placed himself in a false position. He never spoke of the softer passions, save with a gibe and a sneer. They were admirable things for the observer—excellent for drawing the veil from men’s motives and actions. But for the trained reasoner to admit such intrusions into his own delicate and finely adjusted temperament was to introduce a distracting factor which might throw a doubt upon all his mental results. Grit in a sensitive instrument, or a crack in one of his own high-power lenses, would not be more disturbing than a strong emotion in a nature such as his. And yet there was but one woman to him, and that woman was the late Irene Adler, of dubious and questionable memory."}, {"id": 1, "para": 1, "quote": false, "text": "I had seen little of Holmes lately. My marriage had drifted us away from each other. My own complete happiness, and the home-centred interests which rise up around the man who first finds himself master of his own establishment, were sufficient to absorb all my attention, while Holmes, who loathed every form of society with his whole Bohemian soul, remained in our lodgings in Baker Street, buried among his old books, and alternating from week to week between cocaine and ambition, the drowsiness of the drug, and the fierce energy of his own keen nature. He was still, as ever, deeply attracted by the study of crime, and occupied his immense faculties and extraordinary powers of observation in following out those clues, and clearing up those mysteries which had been abandoned as hopeless by the official police. From time to time I heard some vague account of his doings: of his summons to Odessa in the case of the Trepoff murder, of his clearing up of the singular tragedy of the Atkinson brothers at Trincomalee, and finally of the mission which he had accomplished so delicately and successfully for the reigning family of Holland. Beyond these signs of his activity, however, which I merely shared with all the readers of the daily press, I knew little of my former friend and companion."}, {"id": 2, "para": 2, "quote": false, "text": "One night—it was on the twentieth of March, 1888—I was returning from a journey to a patient (for I had now returned to civil practice), when my way led me through Baker Street. As I passed the well-remembered door, which must always be associated in my mind with my wooing, and with the dark incidents of the Study in Scarlet, I was seized with a keen desire to see Holmes again, and to know how he was employing his extraordinary powers. His rooms were brilliantly lit, and, even as I looked up, I saw his tall, spare figure pass twice in a dark silhouette against the blind. He was pacing the room swiftly, eagerly, with his head sunk upon his chest and his hands clasped behind him. To me, who knew his every mood and habit, his attitude and manner told their own story. He was at work again. He had risen out of his drug-created dreams and was hot upon the scent of some new problem. I rang the bell and was shown up to the chamber which had formerly been in part my own."}, {"id": 3, "para": 3, "quote": false, "text": "His manner was not effusive. It seldom was; but he was glad, I think, to see me. With hardly a word spoken, but with a kindly eye, he waved me to an armchair, threw across his case of cigars, and indicated a spirit case and a gasogene in the corner. Then he stood before the fire and looked me over in his singular introspective fashion."}, {"id": 4, "para": 4, "quote": true, "text": "“Wedlock suits you,”", "label": {"speaker": "Sherlock Holmes", "kind": "speech", "emotion": "amused", "intensity": "low"}, "wrong": false}, {"id": 5, "para": 4, "quote": false, "text": "he remarked."}, {"id": 6, "para": 4, "quote": true, "text": "“I think, Watson, that you have put on seven and a half pounds since I saw you.”", "label": {"speaker": "Sherlock Holmes", "kind": "speech", "emotion": "amused", "intensity": "low"}, "wrong": false}, {"id": 7, "para": 5, "quote": true, "text": "“Seven!”", "label": {"speaker": "Watson", "kind": "speech", "emotion": "surprised", "intensity": "low"}, "wrong": false}, {"id": 8, "para": 5, "quote": false, "text": "I answered."}, {"id": 9, "para": 6, "quote": true, "text": "“Indeed, I should have thought a little more. Just a trifle more, I fancy, Watson. And in practice again, I observe. You did not tell me that you intended to go into harness.”", "label": {"speaker": "Sherlock Holmes", "kind": "speech", "emotion": "amused", "intensity": "low"}, "wrong": false}, {"id": 10, "para": 7, "quote": true, "text": "“Then, how do you know?”", "label": {"speaker": "Watson", "kind": "speech", "emotion": "surprised", "intensity": "low"}, "wrong": false}, {"id": 11, "para": 8, "quote": true, "text": "“I see it, I deduce it. How do I know that you have been getting yourself very wet lately, and that you have a most clumsy and careless servant girl?”", "label": {"speaker": "Sherlock Holmes", "kind": "speech", "emotion": "amused", "intensity": "medium"}, "wrong": false}, {"id": 12, "para": 9, "quote": true, "text": "“My dear Holmes,”", "label": {"speaker": "Watson", "kind": "speech", "emotion": "amused", "intensity": "medium"}, "wrong": false}, {"id": 13, "para": 9, "quote": false, "text": "said I,"}, {"id": 14, "para": 9, "quote": true, "text": "“this is too much. You would certainly have been burned, had you lived a few centuries ago. It is true that I had a country walk on Thursday and came home in a dreadful mess, but as I have changed my clothes I can’t imagine how you deduce it. As to Mary Jane, she is incorrigible, and my wife has given her notice, but there, again, I fail to see how you work it out.”", "label": {"speaker": "Watson", "kind": "speech", "emotion": "amused", "intensity": "medium"}, "wrong": false}, {"id": 15, "para": 10, "quote": false, "text": "He chuckled to himself and rubbed his long, nervous hands together."}, {"id": 16, "para": 11, "quote": true, "text": "“It is simplicity itself,”", "label": {"speaker": "Sherlock Holmes", "kind": "speech", "emotion": "amused", "intensity": "low"}, "wrong": false}, {"id": 17, "para": 11, "quote": false, "text": "said he;"}, {"id": 18, "para": 11, "quote": true, "text": "“my eyes tell me that on the inside of your left shoe, just where the firelight strikes it, the leather is scored by six almost parallel cuts. Obviously they have been caused by someone who has very carelessly scraped round the edges of the sole in order to remove crusted mud from it. Hence, you see, my double deduction that you had been out in vile weather, and that you had a particularly malignant boot-slitting specimen of the London slavey. As to your practice, if a gentleman walks into my rooms smelling of iodoform, with a black mark of nitrate of silver upon his right forefinger, and a bulge on the right side of his top-hat to show where he has secreted his stethoscope, I must be dull, indeed, if I do not pronounce him to be an active member of the medical profession.”", "label": {"speaker": "Sherlock Holmes", "kind": "speech", "emotion": "amused", "intensity": "medium"}, "wrong": false}, {"id": 19, "para": 12, "quote": false, "text": "I could not help laughing at the ease with which he explained his process of deduction."}, {"id": 20, "para": 12, "quote": true, "text": "“When I hear you give your reasons,”", "label": {"speaker": "Watson", "kind": "thought", "emotion": "amused", "intensity": "low"}, "wrong": false}, {"id": 21, "para": 12, "quote": false, "text": "I remarked,"}, {"id": 22, "para": 12, "quote": true, "text": "“the thing always appears to me to be so ridiculously simple that I could easily do it myself, though at each successive instance of your reasoning I am baffled until you explain your process. And yet I believe that my eyes are as good as yours.”", "label": {"speaker": "Watson", "kind": "speech", "emotion": "amused", "intensity": "medium"}, "wrong": false}, {"id": 23, "para": 13, "quote": true, "text": "“Quite so,”", "label": {"speaker": "Sherlock Holmes", "kind": "speech", "emotion": "amused", "intensity": "low"}, "wrong": false}, {"id": 24, "para": 13, "quote": false, "text": "he answered, lighting a cigarette, and throwing himself down into an armchair."}, {"id": 25, "para": 13, "quote": true, "text": "“You see, but you do not observe. The distinction is clear. For example, you have frequently seen the steps which lead up from the hall to this room.”", "label": {"speaker": "Sherlock Holmes", "kind": "speech", "emotion": "amused", "intensity": "medium"}, "wrong": false}, {"id": 26, "para": 14, "quote": true, "text": "“Frequently.”", "label": {"speaker": "Watson", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 27, "para": 15, "quote": true, "text": "“How often?”", "label": {"speaker": "Sherlock Holmes", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 28, "para": 16, "quote": true, "text": "“Well, some hundreds of times.”", "label": {"speaker": "Watson", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 29, "para": 17, "quote": true, "text": "“Then how many are there?”", "label": {"speaker": "Sherlock Holmes", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 30, "para": 18, "quote": true, "text": "“How many? I don’t know.”", "label": {"speaker": "Watson", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 31, "para": 19, "quote": true, "text": "“Quite so! You have not observed. And yet you have seen. That is just my point. Now, I know that there are seventeen steps, because I have both seen and observed. By the way, since you are interested in these little problems, and since you are good enough to chronicle one or two of my trifling experiences, you may be interested in this.”", "label": {"speaker": "Sherlock Holmes", "kind": "speech", "emotion": "neutral", "intensity": "medium"}, "wrong": false}, {"id": 32, "para": 19, "quote": false, "text": "He threw over a sheet of thick, pink-tinted notepaper which had been lying open upon the table."}, {"id": 33, "para": 19, "quote": true, "text": "“It came by the last post,”", "label": {"speaker": "Sherlock Holmes", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 34, "para": 19, "quote": false, "text": "said he."}, {"id": 35, "para": 19, "quote": true, "text": "“Read it aloud.”", "label": {"speaker": "Sherlock Holmes", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 36, "para": 20, "quote": false, "text": "The note was undated, and without either signature or address."}, {"id": 37, "para": 21, "quote": true, "text": "“There will call upon you to-night, at a quarter to eight o’clock,”", "label": {"speaker": "Narrator", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 38, "para": 21, "quote": false, "text": "it said,"}, {"id": 39, "para": 21, "quote": true, "text": "“a gentleman who desires to consult you upon a matter of the very deepest moment. Your recent services to one of the royal houses of Europe have shown that you are one who may safely be trusted with matters which are of an importance which can hardly be exaggerated. This account of you we have from all quarters received. Be in your chamber then at that hour, and do not take it amiss if your visitor wear a mask.”", "label": {"speaker": "Narrator", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 40, "para": 22, "quote": true, "text": "“This is indeed a mystery,”", "label": {"speaker": "Watson", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 41, "para": 22, "quote": false, "text": "I remarked."}, {"id": 42, "para": 22, "quote": true, "text": "“What do you imagine that it means?”", "label": {"speaker": "Watson", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 43, "para": 23, "quote": true, "text": "“I have no data yet. It is a capital mistake to theorise before one has data. Insensibly one begins to twist facts to suit theories, instead of theories to suit facts. But the note itself. What do you deduce from it?”", "label": {"speaker": "Watson", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": true}, {"id": 44, "para": 24, "quote": false, "text": "I carefully examined the writing, and the paper upon which it was written."}, {"id": 45, "para": 25, "quote": true, "text": "“The man who wrote it was presumably well to do,”", "label": {"speaker": "Watson", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 46, "para": 25, "quote": false, "text": "I remarked, endeavouring to imitate my companion’s processes."}, {"id": 47, "para": 25, "quote": true, "text": "“Such paper could not be bought under half a crown a packet. It is peculiarly strong and stiff.”", "label": {"speaker": "Watson", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 48, "para": 26, "quote": true, "text": "“Peculiar—that is the very word,”", "label": {"speaker": "Sherlock Holmes", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 49, "para": 26, "quote": false, "text": "said Holmes."}, {"id": 50, "para": 26, "quote": true, "text": "“It is not an English paper at all. Hold it up to the light.”", "label": {"speaker": "Sherlock Holmes", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 51, "para": 27, "quote": false, "text": "I did so, and saw a large"}, {"id": 52, "para": 27, "quote": true, "text": "“E”", "label": {"speaker": "Narrator", "kind": "thought", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 53, "para": 27, "quote": false, "text": "with a small"}, {"id": 54, "para": 27, "quote": true, "text": "“g,”", "label": {"speaker": "Narrator", "kind": "thought", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 55, "para": 27, "quote": false, "text": "a"}, {"id": 56, "para": 27, "quote": true, "text": "“P,”", "label": {"speaker": "Narrator", "kind": "thought", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 57, "para": 27, "quote": false, "text": "and a large"}, {"id": 58, "para": 27, "quote": true, "text": "“G”", "label": {"speaker": "Narrator", "kind": "thought", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 59, "para": 27, "quote": false, "text": "with a small"}, {"id": 60, "para": 27, "quote": true, "text": "“t”", "label": {"speaker": "Narrator", "kind": "thought", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 61, "para": 27, "quote": false, "text": "woven into the texture of the paper."}, {"id": 62, "para": 28, "quote": true, "text": "“What do you make of that?”", "label": {"speaker": "Sherlock Holmes", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 63, "para": 28, "quote": false, "text": "asked Holmes."}, {"id": 64, "para": 29, "quote": true, "text": "“The name of the maker, no doubt; or his monogram, rather.”", "label": {"speaker": "Watson", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 65, "para": 30, "quote": true, "text": "“Not at all. The ‘G’ with the small ‘t’ stands for ‘Gesellschaft,’ which is the German for ‘Company.’ It is a customary contraction like our ‘Co.’ ‘P,’ of course, stands for ‘Papier.’ Now for the ‘Eg.’ Let us glance at our Continental Gazetteer.”", "label": {"speaker": "Sherlock Holmes", "kind": "speech", "emotion": "neutral", "intensity": "medium"}, "wrong": false}, {"id": 66, "para": 30, "quote": false, "text": "He took down a heavy brown volume from his shelves."}, {"id": 67, "para": 30, "quote": true, "text": "“Eglow, Eglonitz—here we are, Egria. It is in a German-speaking country—in Bohemia, not far from Carlsbad. ‘Remarkable as being the scene of the death of Wallenstein, and for its numerous glass-factories and paper-mills.’ Ha, ha, my boy, what do you make of that?”", "label": {"speaker": "Sherlock Holmes", "kind": "speech", "emotion": "amused", "intensity": "medium"}, "wrong": false}, {"id": 68, "para": 30, "quote": false, "text": "His eyes sparkled, and he sent up a great blue triumphant cloud from his cigarette."}], "narrator": {"person": "first", "character": "Watson"}, "characters": [{"name": "Watson", "aliases": [], "gender": "unknown", "age": "unknown"}, {"name": "Sherlock Holmes", "aliases": ["Holmes", "the woman's admirer", "the most perfect reasoning and observing machine", "my former friend and companion", "my companion", "my friend", "my boy", "he"], "gender": "male", "age": "adult"}, {"name": "Irene Adler", "aliases": ["Irene Adler", "the late Irene Adler", "the woman", "the one woman to him"], "gender": "female", "age": "adult"}, {"name": "Mary Jane", "aliases": ["Mary Jane", "my servant girl"], "gender": "female", "age": "adult"}, {"name": "the patient", "aliases": ["a patient"], "gender": "unknown", "age": "unknown"}, {"name": "the visitor", "aliases": ["a gentleman", "your visitor"], "gender": "unknown", "age": "unknown"}, {"name": "the writer", "aliases": ["the man who wrote it"], "gender": "unknown", "age": "unknown"}, {"name": "the maker", "aliases": ["the maker"], "gender": "unknown", "age": "unknown"}], "scenes": [{"first_paragraph": 0, "setting": "Holmes's study", "mood": "melancholic"}, {"first_paragraph": 1, "setting": "Baker Street", "mood": "melancholic"}, {"first_paragraph": 2, "setting": "Baker Street", "mood": "anxious"}, {"first_paragraph": 3, "setting": "Holmes's study", "mood": "calm"}, {"first_paragraph": 4, "setting": "Holmes's study", "mood": "calm"}]}, {"id": "04-jane-eyre-ch1", "title": "Jane Eyre, Chapter I - Charlotte Bronte", "lines": [{"id": 0, "para": 0, "quote": false, "text": "There was no possibility of taking a walk that day. We had been wandering, indeed, in the leafless shrubbery an hour in the morning; but since dinner (Mrs. Reed, when there was no company, dined early) the cold winter wind had brought with it clouds so sombre, and a rain so penetrating, that further outdoor exercise was now out of the question."}, {"id": 1, "para": 1, "quote": false, "text": "I was glad of it: I never liked long walks, especially on chilly afternoons: dreadful to me was the coming home in the raw twilight, with nipped fingers and toes, and a heart saddened by the chidings of Bessie, the nurse, and humbled by the consciousness of my physical inferiority to Eliza, John, and Georgiana Reed."}, {"id": 2, "para": 2, "quote": false, "text": "The said Eliza, John, and Georgiana were now clustered round their mama in the drawing-room: she lay reclined on a sofa by the fireside, and with her darlings about her (for the time neither quarrelling nor crying) looked perfectly happy. Me, she had dispensed from joining the group; saying,"}, {"id": 3, "para": 2, "quote": true, "text": "“She regretted to be under the necessity of keeping me at a distance; but that until she heard from Bessie, and could discover by her own observation, that I was endeavouring in good earnest to acquire a more sociable and childlike disposition, a more attractive and sprightly manner—something lighter, franker, more natural, as it were—she really must exclude me from privileges intended only for contented, happy, little children.”", "label": {"speaker": "Mrs. Reed", "kind": "speech", "emotion": "disgusted", "intensity": "medium"}, "wrong": false}, {"id": 4, "para": 3, "quote": true, "text": "“What does Bessie say I have done?”", "label": {"speaker": "Jane", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": false}, {"id": 5, "para": 3, "quote": false, "text": "I asked."}, {"id": 6, "para": 4, "quote": true, "text": "“Jane, I don’t like cavillers or questioners; besides, there is something truly forbidding in a child taking up her elders in that manner. Be seated somewhere; and until you can speak pleasantly, remain silent.”", "label": {"speaker": "Mrs. Reed", "kind": "speech", "emotion": "disgusted", "intensity": "high"}, "wrong": false}, {"id": 7, "para": 5, "quote": false, "text": "A breakfast-room adjoined the drawing-room, I slipped in there. It contained a bookcase: I soon possessed myself of a volume, taking care that it should be one stored with pictures. I mounted into the window-seat: gathering up my feet, I sat cross-legged, like a Turk; and, having drawn the red moreen curtain nearly close, I was shrined in double retirement."}, {"id": 8, "para": 6, "quote": false, "text": "Folds of scarlet drapery shut in my view to the right hand; to the left were the clear panes of glass, protecting, but not separating me from the drear November day. At intervals, while turning over the leaves of my book, I studied the aspect of that winter afternoon. Afar, it offered a pale blank of mist and cloud; near a scene of wet lawn and storm-beat shrub, with ceaseless rain sweeping away wildly before a long and lamentable blast."}, {"id": 9, "para": 7, "quote": false, "text": "I returned to my book—Bewick’s History of British Birds: the letterpress thereof I cared little for, generally speaking; and yet there were certain introductory pages that, child as I was, I could not pass quite as a blank. They were those which treat of the haunts of sea-fowl; of"}, {"id": 10, "para": 7, "quote": true, "text": "“the solitary rocks and promontories”", "label": {"speaker": "Narrator", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 11, "para": 7, "quote": false, "text": "by them only inhabited; of the coast of Norway, studded with isles from its southern extremity, the Lindeness, or Naze, to the North Cape—"}, {"id": 12, "para": 8, "quote": true, "text": "“Where the Northern Ocean, in vast whirls, Boils round the naked, melancholy isles Of farthest Thule; and the Atlantic surge Pours in among the stormy Hebrides.”", "label": {"speaker": "Narrator", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 13, "para": 9, "quote": false, "text": "Nor could I pass unnoticed the suggestion of the bleak shores of Lapland, Siberia, Spitzbergen, Nova Zembla, Iceland, Greenland, with"}, {"id": 14, "para": 9, "quote": true, "text": "“the vast sweep of the Arctic Zone, and those forlorn regions of dreary space,—that reservoir of frost and snow, where firm fields of ice, the accumulation of centuries of winters, glazed in Alpine heights above heights, surround the pole, and concentre the multiplied rigours of extreme cold.”", "label": {"speaker": "Narrator", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 15, "para": 9, "quote": false, "text": "Of these death-white realms I formed an idea of my own: shadowy, like all the half-comprehended notions that float dim through children’s brains, but strangely impressive. The words in these introductory pages connected themselves with the succeeding vignettes, and gave significance to the rock standing up alone in a sea of billow and spray; to the broken boat stranded on a desolate coast; to the cold and ghastly moon glancing through bars of cloud at a wreck just sinking."}, {"id": 16, "para": 10, "quote": false, "text": "I cannot tell what sentiment haunted the quite solitary churchyard, with its inscribed headstone; its gate, its two trees, its low horizon, girdled by a broken wall, and its newly-risen crescent, attesting the hour of eventide."}, {"id": 17, "para": 11, "quote": false, "text": "The two ships becalmed on a torpid sea, I believed to be marine phantoms."}, {"id": 18, "para": 12, "quote": false, "text": "The fiend pinning down the thief’s pack behind him, I passed over quickly: it was an object of terror."}, {"id": 19, "para": 13, "quote": false, "text": "So was the black horned thing seated aloof on a rock, surveying a distant crowd surrounding a gallows."}, {"id": 20, "para": 14, "quote": false, "text": "Each picture told a story; mysterious often to my undeveloped understanding and imperfect feelings, yet ever profoundly interesting: as interesting as the tales Bessie sometimes narrated on winter evenings, when she chanced to be in good humour; and when, having brought her ironing-table to the nursery hearth, she allowed us to sit about it, and while she got up Mrs. Reed’s lace frills, and crimped her nightcap borders, fed our eager attention with passages of love and adventure taken from old fairy tales and other ballads; or (as at a later period I discovered) from the pages of Pamela, and Henry, Earl of Moreland."}, {"id": 21, "para": 15, "quote": false, "text": "With Bewick on my knee, I was then happy: happy at least in my way. I feared nothing but interruption, and that came too soon. The breakfast-room door opened."}, {"id": 22, "para": 16, "quote": true, "text": "“Boh! Madam Mope!”", "label": {"speaker": "John Reed", "kind": "speech", "emotion": "disgusted", "intensity": "medium"}, "wrong": false}, {"id": 23, "para": 16, "quote": false, "text": "cried the voice of John Reed; then he paused: he found the room apparently empty."}, {"id": 24, "para": 17, "quote": true, "text": "“Where the dickens is she!”", "label": {"speaker": "John Reed", "kind": "speech", "emotion": "angry", "intensity": "medium"}, "wrong": false}, {"id": 25, "para": 17, "quote": false, "text": "he continued."}, {"id": 26, "para": 17, "quote": true, "text": "“Lizzy! Georgy! (calling to his sisters) Joan is not here: tell mama she is run out into the rain—bad animal!”", "label": {"speaker": "John Reed", "kind": "speech", "emotion": "angry", "intensity": "high"}, "wrong": false}, {"id": 27, "para": 18, "quote": true, "text": "“It is well I drew the curtain,”", "label": {"speaker": "Jane", "kind": "thought", "emotion": "anxious", "intensity": "medium"}, "wrong": false}, {"id": 28, "para": 18, "quote": false, "text": "thought I; and I wished fervently he might not discover my hiding-place: nor would John Reed have found it out himself; he was not quick either of vision or conception; but Eliza just put her head in at the door, and said at once—"}, {"id": 29, "para": 19, "quote": true, "text": "“She is in the window-seat, to be sure, Jack.”", "label": {"speaker": "Eliza Reed", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 30, "para": 20, "quote": false, "text": "And I came out immediately, for I trembled at the idea of being dragged forth by the said Jack."}, {"id": 31, "para": 21, "quote": true, "text": "“What do you want?”", "label": {"speaker": "Jane", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 32, "para": 21, "quote": false, "text": "I asked, with awkward diffidence."}, {"id": 33, "para": 22, "quote": true, "text": "“Say, ‘What do you want, Master Reed?’”", "label": {"speaker": "John Reed", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 34, "para": 22, "quote": false, "text": "was the answer."}, {"id": 35, "para": 22, "quote": true, "text": "“I want you to come here;”", "label": {"speaker": "John Reed", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 36, "para": 22, "quote": false, "text": "and seating himself in an arm-chair, he intimated by a gesture that I was to approach and stand before him."}, {"id": 37, "para": 23, "quote": false, "text": "John Reed was a schoolboy of fourteen years old; four years older than I, for I was but ten: large and stout for his age, with a dingy and unwholesome skin; thick lineaments in a spacious visage, heavy limbs and large extremities. He gorged himself habitually at table, which made him bilious, and gave him a dim and bleared eye and flabby cheeks. He ought now to have been at school; but his mama had taken him home for a month or two,"}, {"id": 38, "para": 23, "quote": true, "text": "“on account of his delicate health.”", "label": {"speaker": "Narrator", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 39, "para": 23, "quote": false, "text": "Mr. Miles, the master, affirmed that he would do very well if he had fewer cakes and sweetmeats sent him from home; but the mother’s heart turned from an opinion so harsh, and inclined rather to the more refined idea that John’s sallowness was owing to over-application and, perhaps, to pining after home."}, {"id": 40, "para": 24, "quote": false, "text": "John had not much affection for his mother and sisters, and an antipathy to me. He bullied and punished me; not two or three times in the week, nor once or twice in the day, but continually: every nerve I had feared him, and every morsel of flesh in my bones shrank when he came near. There were moments when I was bewildered by the terror he inspired, because I had no appeal whatever against either his menaces or his inflictions; the servants did not like to offend their young master by taking my part against him, and Mrs. Reed was blind and deaf on the subject: she never saw him strike or heard him abuse me, though he did both now and then in her very presence, more frequently, however, behind her back."}, {"id": 41, "para": 25, "quote": false, "text": "Habitually obedient to John, I came up to his chair: he spent some three minutes in thrusting out his tongue at me as far as he could without damaging the roots: I knew he would soon strike, and while dreading the blow, I mused on the disgusting and ugly appearance of him who would presently deal it. I wonder if he read that notion in my face; for, all at once, without speaking, he struck suddenly and strongly. I tottered, and on regaining my equilibrium retired back a step or two from his chair."}, {"id": 42, "para": 26, "quote": true, "text": "“That is for your impudence in answering mama awhile since,”", "label": {"speaker": "John Reed", "kind": "speech", "emotion": "angry", "intensity": "high"}, "wrong": false}, {"id": 43, "para": 26, "quote": false, "text": "said he,"}, {"id": 44, "para": 26, "quote": true, "text": "“and for your sneaking way of getting behind curtains, and for the look you had in your eyes two minutes since, you rat!”", "label": {"speaker": "John Reed", "kind": "speech", "emotion": "angry", "intensity": "high"}, "wrong": false}, {"id": 45, "para": 27, "quote": false, "text": "Accustomed to John Reed’s abuse, I never had an idea of replying to it; my care was how to endure the blow which would certainly follow the insult."}, {"id": 46, "para": 28, "quote": true, "text": "“What were you doing behind the curtain?”", "label": {"speaker": "John Reed", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 47, "para": 28, "quote": false, "text": "he asked."}, {"id": 48, "para": 29, "quote": true, "text": "“I was reading.”", "label": {"speaker": "Jane", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 49, "para": 30, "quote": true, "text": "“Show the book.”", "label": {"speaker": "John Reed", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": false}, {"id": 50, "para": 31, "quote": false, "text": "I returned to the window and fetched it thence."}, {"id": 51, "para": 32, "quote": true, "text": "“You have no business to take our books; you are a dependent, mama says; you have no money; your father left you none; you ought to beg, and not to live here with gentlemen’s children like us, and eat the same meals we do, and wear clothes at our mama’s expense. Now, I’ll teach you to rummage my bookshelves: for they _are_ mine; all the house belongs to me, or will do in a few years. Go and stand by the door, out of the way of the mirror and the windows.”", "label": {"speaker": "John Reed", "kind": "speech", "emotion": "angry", "intensity": "high"}, "wrong": false}, {"id": 52, "para": 33, "quote": false, "text": "I did so, not at first aware what was his intention; but when I saw him lift and poise the book and stand in act to hurl it, I instinctively started aside with a cry of alarm: not soon enough, however; the volume was flung, it hit me, and I fell, striking my head against the door and cutting it. The cut bled, the pain was sharp: my terror had passed its climax; other feelings succeeded."}, {"id": 53, "para": 34, "quote": true, "text": "“Wicked and cruel boy!”", "label": {"speaker": "Jane", "kind": "speech", "emotion": "happy", "intensity": "medium"}, "wrong": false}, {"id": 54, "para": 34, "quote": false, "text": "I said."}, {"id": 55, "para": 34, "quote": true, "text": "“You are like a murderer—you are like a slave-driver—you are like the Roman emperors!”", "label": {"speaker": "Jane", "kind": "speech", "emotion": "happy", "intensity": "high"}, "wrong": false}, {"id": 56, "para": 35, "quote": false, "text": "I had read Goldsmith’s History of Rome, and had formed my opinion of Nero, Caligula, &c. Also I had drawn parallels in silence, which I never thought thus to have declared aloud."}, {"id": 57, "para": 36, "quote": true, "text": "“What! what!”", "label": {"speaker": "John Reed", "kind": "speech", "emotion": "surprised", "intensity": "high"}, "wrong": false}, {"id": 58, "para": 36, "quote": false, "text": "he cried."}, {"id": 59, "para": 36, "quote": true, "text": "“Did she say that to me? Did you hear her, Eliza and Georgiana? Won’t I tell mama? but first—”", "label": {"speaker": "John Reed", "kind": "speech", "emotion": "angry", "intensity": "high"}, "wrong": false}, {"id": 60, "para": 37, "quote": false, "text": "He ran headlong at me: I felt him grasp my hair and my shoulder: he had closed with a desperate thing. I really saw in him a tyrant, a murderer. I felt a drop or two of blood from my head trickle down my neck, and was sensible of somewhat pungent suffering: these sensations for the time predominated over fear, and I received him in frantic sort. I don’t very well know what I did with my hands, but he called me"}, {"id": 61, "para": 37, "quote": true, "text": "“Rat! Rat!”", "label": {"speaker": "Jane", "kind": "speech", "emotion": "happy", "intensity": "low"}, "wrong": true}, {"id": 62, "para": 37, "quote": false, "text": "and bellowed out aloud. Aid was near him: Eliza and Georgiana had run for Mrs. Reed, who was gone upstairs: she now came upon the scene, followed by Bessie and her maid Abbot. We were parted: I heard the words—"}, {"id": 63, "para": 38, "quote": true, "text": "“Dear! dear! What a fury to fly at Master John!”", "label": {"speaker": "Mrs. Reed", "kind": "speech", "emotion": "disgusted", "intensity": "medium"}, "wrong": true}, {"id": 64, "para": 39, "quote": true, "text": "“Did ever anybody see such a picture of passion!”", "label": {"speaker": "Mrs. Reed", "kind": "speech", "emotion": "disgusted", "intensity": "medium"}, "wrong": true}, {"id": 65, "para": 40, "quote": false, "text": "Then Mrs. Reed subjoined—"}, {"id": 66, "para": 41, "quote": true, "text": "“Take her away to the red-room, and lock her in there.”", "label": {"speaker": "Mrs. Reed", "kind": "speech", "emotion": "angry", "intensity": "high"}, "wrong": false}, {"id": 67, "para": 41, "quote": false, "text": "Four hands were immediately laid upon me, and I was borne upstairs."}], "narrator": {"person": "first", "character": "Jane"}, "characters": [{"name": "Jane", "aliases": ["I"], "gender": "female", "age": "child"}, {"name": "Mrs. Reed", "aliases": ["mama", "Madam Mope", "Mrs. Reed"], "gender": "female", "age": "adult"}, {"name": "Bessie", "aliases": ["the nurse", "Bessie"], "gender": "female", "age": "adult"}, {"name": "Eliza Reed", "aliases": ["Eliza", "Lizzy", "Eliza Reed"], "gender": "female", "age": "child"}, {"name": "John Reed", "aliases": ["John", "Jack", "Master Reed", "Master John"], "gender": "male", "age": "child"}, {"name": "Georgiana Reed", "aliases": ["Georgiana", "Georgy", "Georgiana Reed"], "gender": "female", "age": "child"}, {"name": "Joan", "aliases": ["Joan"], "gender": "female", "age": "child"}, {"name": "Mr. Miles", "aliases": ["the master", "Mr. Miles"], "gender": "male", "age": "adult"}, {"name": "Abbot", "aliases": ["her maid", "Abbot"], "gender": "female", "age": "adult"}], "scenes": [{"first_paragraph": 1, "setting": "The drawing-room and adjacent breakfast-room", "mood": "melancholic"}, {"first_paragraph": 16, "setting": "The breakfast-room", "mood": "tense"}, {"first_paragraph": 25, "setting": "The breakfast-room", "mood": "angry"}]}, {"id": "05-metamorphosis-opening", "title": "Metamorphosis, Part I (opening) - Franz Kafka (tr. David Wyllie)", "lines": [{"id": 0, "para": 0, "quote": false, "text": "One morning, when Gregor Samsa woke from troubled dreams, he found himself transformed in his bed into a horrible vermin. He lay on his armour-like back, and if he lifted his head a little he could see his brown belly, slightly domed and divided by arches into stiff sections. The bedding was hardly able to cover it and seemed ready to slide off any moment. His many legs, pitifully thin compared with the size of the rest of him, waved about helplessly as he looked."}, {"id": 1, "para": 1, "quote": true, "text": "“What’s happened to me?”", "label": {"speaker": "Gregor Samsa", "kind": "thought", "emotion": "disgusted", "intensity": "high"}, "wrong": false}, {"id": 2, "para": 1, "quote": false, "text": "he thought. It wasn’t a dream. His room, a proper human room although a little too small, lay peacefully between its four familiar walls. A collection of textile samples lay spread out on the table—Samsa was a travelling salesman—and above it there hung a picture that he had recently cut out of an illustrated magazine and housed in a nice, gilded frame. It showed a lady fitted out with a fur hat and fur boa who sat upright, raising a heavy fur muff that covered the whole of her lower arm towards the viewer."}, {"id": 3, "para": 2, "quote": false, "text": "Gregor then turned to look out the window at the dull weather. Drops of rain could be heard hitting the pane, which made him feel quite sad."}, {"id": 4, "para": 2, "quote": true, "text": "“How about if I sleep a little bit longer and forget all this nonsense”", "label": {"speaker": "Gregor Samsa", "kind": "thought", "emotion": "sad", "intensity": "medium"}, "wrong": false}, {"id": 5, "para": 2, "quote": false, "text": ", he thought, but that was something he was unable to do because he was used to sleeping on his right, and in his present state couldn’t get into that position. However hard he threw himself onto his right, he always rolled back to where he was. He must have tried it a hundred times, shut his eyes so that he wouldn’t have to look at the floundering legs, and only stopped when he began to feel a mild, dull pain there that he had never felt before."}, {"id": 6, "para": 3, "quote": true, "text": "“Oh, God”", "label": {"speaker": "Gregor Samsa", "kind": "thought", "emotion": "happy", "intensity": "medium"}, "wrong": false}, {"id": 7, "para": 3, "quote": false, "text": ", he thought,"}, {"id": 8, "para": 3, "quote": true, "text": "“what a strenuous career it is that I’ve chosen! Travelling day in and day out. Doing business like this takes much more effort than doing your own business at home, and on top of that there’s the curse of travelling, worries about making train connections, bad and irregular food, contact with different people all the time so that you can never get to know anyone or become friendly with them. It can all go to Hell!”", "label": {"speaker": "Gregor Samsa", "kind": "thought", "emotion": "angry", "intensity": "high"}, "wrong": false}, {"id": 9, "para": 3, "quote": false, "text": "He felt a slight itch up on his belly; pushed himself slowly up on his back towards the headboard so that he could lift his head better; found where the itch was, and saw that it was covered with lots of little white spots which he didn’t know what to make of; and when he tried to feel the place with one of his legs he drew it quickly back because as soon as he touched it he was overcome by a cold shudder."}, {"id": 10, "para": 4, "quote": false, "text": "He slid back into his former position."}, {"id": 11, "para": 4, "quote": true, "text": "“Getting up early all the time”", "label": {"speaker": "Gregor Samsa", "kind": "thought", "emotion": "sad", "intensity": "medium"}, "wrong": false}, {"id": 12, "para": 4, "quote": false, "text": ", he thought,"}, {"id": 13, "para": 4, "quote": true, "text": "“it makes you stupid. You’ve got to get enough sleep. Other travelling salesmen live a life of luxury. For instance, whenever I go back to the guest house during the morning to copy out the contract, these gentlemen are always still sitting there eating their breakfasts. I ought to just try that with my boss; I’d get kicked out on the spot. But who knows, maybe that would be the best thing for me. If I didn’t have my parents to think about I’d have given in my notice a long time ago, I’d have gone up to the boss and told him just what I think, tell him everything I would, let him know just what I feel. He’d fall right off his desk! And it’s a funny sort of business to be sitting up there at your desk, talking down at your subordinates from up there, especially when you have to go right up close because the boss is hard of hearing. Well, there’s still some hope; once I’ve got the money together to pay off my parents’ debt to him—another five or six years I suppose—that’s definitely what I’ll do. That’s when I’ll make the big change. First of all though, I’ve got to get up, my train leaves at five.”", "label": {"speaker": "Gregor Samsa", "kind": "thought", "emotion": "angry", "intensity": "high"}, "wrong": false}, {"id": 14, "para": 5, "quote": false, "text": "And he looked over at the alarm clock, ticking on the chest of drawers."}, {"id": 15, "para": 5, "quote": true, "text": "“God in Heaven!”", "label": {"speaker": "Gregor Samsa", "kind": "thought", "emotion": "surprised", "intensity": "high"}, "wrong": false}, {"id": 16, "para": 5, "quote": false, "text": "he thought. It was half past six and the hands were quietly moving forwards, it was even later than half past, more like quarter to seven. Had the alarm clock not rung? He could see from the bed that it had been set for four o’clock as it should have been; it certainly must have rung. Yes, but was it possible to quietly sleep through that furniture-rattling noise? True, he had not slept peacefully, but probably all the more deeply because of that. What should he do now? The next train went at seven; if he were to catch that he would have to rush like mad and the collection of samples was still not packed, and he did not at all feel particularly fresh and lively. And even if he did catch the train he would not avoid his boss’s anger as the office assistant would have been there to see the five o’clock train go, he would have put in his report about Gregor’s not being there a long time ago. The office assistant was the boss’s man, spineless, and with no understanding. What about if he reported sick? But that would be extremely strained and suspicious as in five years of service Gregor had never once yet been ill. His boss would certainly come round with the doctor from the medical insurance company, accuse his parents of having a lazy son, and accept the doctor’s recommendation not to make any claim as the doctor believed that no-one was ever ill but that many were workshy. And what’s more, would he have been entirely wrong in this case? Gregor did in fact, apart from excessive sleepiness after sleeping for so long, feel completely well and even felt much hungrier than usual."}, {"id": 17, "para": 6, "quote": false, "text": "He was still hurriedly thinking all this through, unable to decide to get out of the bed, when the clock struck quarter to seven. There was a cautious knock at the door near his head."}, {"id": 18, "para": 6, "quote": true, "text": "“Gregor”", "label": {"speaker": "Unknown", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": true}, {"id": 19, "para": 6, "quote": false, "text": ", somebody called—it was his mother—"}, {"id": 20, "para": 6, "quote": true, "text": "“it’s quarter to seven. Didn’t you want to go somewhere?”", "label": {"speaker": "Unknown", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": true}, {"id": 21, "para": 6, "quote": false, "text": "That gentle voice! Gregor was shocked when he heard his own voice answering, it could hardly be recognised as the voice he had had before. As if from deep inside him, there was a painful and uncontrollable squeaking mixed in with it, the words could be made out at first but then there was a sort of echo which made them unclear, leaving the hearer unsure whether he had heard properly or not. Gregor had wanted to give a full answer and explain everything, but in the circumstances contented himself with saying:"}, {"id": 22, "para": 6, "quote": true, "text": "“Yes, mother, yes, thank-you, I’m getting up now.”", "label": {"speaker": "Gregor Samsa", "kind": "speech", "emotion": "anxious", "intensity": "medium"}, "wrong": false}, {"id": 23, "para": 6, "quote": false, "text": "The change in Gregor’s voice probably could not be noticed outside through the wooden door, as his mother was satisfied with this explanation and shuffled away. But this short conversation made the other members of the family aware that Gregor, against their expectations was still at home, and soon his father came knocking at one of the side doors, gently, but with his fist."}, {"id": 24, "para": 6, "quote": true, "text": "“Gregor, Gregor”", "label": {"speaker": "Unknown", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": true}, {"id": 25, "para": 6, "quote": false, "text": ", he called,"}, {"id": 26, "para": 6, "quote": true, "text": "“what’s wrong?”", "label": {"speaker": "Unknown", "kind": "speech", "emotion": "neutral", "intensity": "low"}, "wrong": true}, {"id": 27, "para": 6, "quote": false, "text": "And after a short while he called again with a warning deepness in his voice:"}, {"id": 28, "para": 6, "quote": true, "text": "“Gregor! Gregor!”", "label": {"speaker": "Unknown", "kind": "speech", "emotion": "angry", "intensity": "medium"}, "wrong": true}, {"id": 29, "para": 6, "quote": false, "text": "At the other side door his sister came plaintively:"}, {"id": 30, "para": 6, "quote": true, "text": "“Gregor? Aren’t you well? Do you need anything?”", "label": {"speaker": "Unknown", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": true}, {"id": 31, "para": 6, "quote": false, "text": "Gregor answered to both sides:"}, {"id": 32, "para": 6, "quote": true, "text": "“I’m ready, now”", "label": {"speaker": "Gregor Samsa", "kind": "speech", "emotion": "anxious", "intensity": "medium"}, "wrong": false}, {"id": 33, "para": 6, "quote": false, "text": ", making an effort to remove all the strangeness from his voice by enunciating very carefully and putting long pauses between each, individual word. His father went back to his breakfast, but his sister whispered:"}, {"id": 34, "para": 6, "quote": true, "text": "“Gregor, open the door, I beg of you.”", "label": {"speaker": "Unknown", "kind": "speech", "emotion": "anxious", "intensity": "low"}, "wrong": true}, {"id": 35, "para": 6, "quote": false, "text": "Gregor, however, had no thought of opening the door, and instead congratulated himself for his cautious habit, acquired from his travelling, of locking all doors at night even when he was at home."}, {"id": 36, "para": 7, "quote": false, "text": "The first thing he wanted to do was to get up in peace without being disturbed, to get dressed, and most of all to have his breakfast. Only then would he consider what to do next, as he was well aware that he would not bring his thoughts to any sensible conclusions by lying in bed. He remembered that he had often felt a slight pain in bed, perhaps caused by lying awkwardly, but that had always turned out to be pure imagination and he wondered how his imaginings would slowly resolve themselves today. He did not have the slightest doubt that the change in his voice was nothing more than the first sign of a serious cold, which was an occupational hazard for travelling salesmen."}, {"id": 37, "para": 8, "quote": false, "text": "It was a simple matter to throw off the covers; he only had to blow himself up a little and they fell off by themselves. But it became difficult after that, especially as he was so exceptionally broad. He would have used his arms and his hands to push himself up; but instead of them he only had all those little legs continuously moving in different directions, and which he was moreover unable to control. If he wanted to bend one of them, then that was the first one that would stretch itself out; and if he finally managed to do what he wanted with that leg, all the others seemed to be set free and would move about painfully."}, {"id": 38, "para": 8, "quote": true, "text": "“This is something that can’t be done in bed”", "label": {"speaker": "Gregor Samsa", "kind": "thought", "emotion": "disgusted", "intensity": "high"}, "wrong": false}, {"id": 39, "para": 8, "quote": false, "text": ", Gregor said to himself,"}, {"id": 40, "para": 8, "quote": true, "text": "“so don’t keep trying to do it”", "label": {"speaker": "Gregor Samsa", "kind": "thought", "emotion": "disgusted", "intensity": "high"}, "wrong": false}, {"id": 41, "para": 8, "quote": false, "text": "."}], "narrator": {"person": "third", "character": ""}, "characters": [{"name": "Gregor Samsa", "aliases": ["Gregor", "Samsa", "the salesman", "my dear (implied by context of parents)", "travelling salesman", "subordinate", "employee", "son"], "gender": "male", "age": "adult"}], "scenes": [{"first_paragraph": 1, "setting": "Gregor's bedroom", "mood": "tense"}, {"first_paragraph": 3, "setting": "Gregor's bedroom", "mood": "melancholic"}, {"first_paragraph": 5, "setting": "Gregor's bedroom", "mood": "anxious"}]}, {"id": "06-crime-and-punishment-opening", "title": "Crime and Punishment, Part I, Chapter I (opening) - Fyodor Dostoevsky (tr. Constance Garnett)", "lines": [{"id": 0, "para": 0, "quote": false, "text": "On an exceptionally hot evening early in July a young man came out of the garret in which he lodged in S. Place and walked slowly, as though in hesitation, towards K. bridge."}, {"id": 1, "para": 1, "quote": false, "text": "He had successfully avoided meeting his landlady on the staircase. His garret was under the roof of a high, five-storied house and was more like a cupboard than a room. The landlady who provided him with garret, dinners, and attendance, lived on the floor below, and every time he went out he was obliged to pass her kitchen, the door of which invariably stood open. And each time he passed, the young man had a sick, frightened feeling, which made him scowl and feel ashamed. He was hopelessly in debt to his landlady, and was afraid of meeting her."}, {"id": 2, "para": 2, "quote": false, "text": "This was not because he was cowardly and abject, quite the contrary; but for some time past he had been in an overstrained irritable condition, verging on hypochondria. He had become so completely absorbed in himself, and isolated from his fellows that he dreaded meeting, not only his landlady, but anyone at all. He was crushed by poverty, but the anxieties of his position had of late ceased to weigh upon him. He had given up attending to matters of practical importance; he had lost all desire to do so. Nothing that any landlady could do had a real terror for him. But to be stopped on the stairs, to be forced to listen to her trivial, irrelevant gossip, to pestering demands for payment, threats and complaints, and to rack his brains for excuses, to prevaricate, to lie--no, rather than that, he would creep down the stairs like a cat and slip out unseen."}, {"id": 3, "para": 3, "quote": false, "text": "This evening, however, on coming out into the street, he became acutely aware of his fears."}, {"id": 4, "para": 4, "quote": true, "text": "“I want to attempt a thing _like that_ and am frightened by these trifles,”", "label": {"speaker": "the young man", "kind": "thought", "emotion": "disgusted", "intensity": "low"}, "wrong": false}, {"id": 5, "para": 4, "quote": false, "text": "he thought, with an odd smile."}, {"id": 6, "para": 4, "quote": true, "text": "“Hm... yes, all is in a man’s hands and he lets it all slip from cowardice, that’s an axiom. It would be interesting to know what it is men are most afraid of. Taking a new step, uttering a new word is what they fear most.... But I am talking too much. It’s because I chatter that I do nothing. Or perhaps it is that I chatter because I do nothing. I’ve learned to chatter this last month, lying for days together in my den thinking... of Jack the Giant-killer. Why am I going there now? Am I capable of _that_? Is _that_ serious? It is not serious at all. It’s simply a fantasy to amuse myself; a plaything! Yes, maybe it is a plaything.”", "label": {"speaker": "the young man", "kind": "thought", "emotion": "anxious", "intensity": "medium"}, "wrong": false}, {"id": 7, "para": 5, "quote": false, "text": "The heat in the street was terrible: and the airlessness, the bustle and the plaster, scaffolding, bricks, and dust all about him, and that special Petersburg stench, so familiar to all who are unable to get out of town in summer--all worked painfully upon the young man’s already overwrought nerves. The insufferable stench from the pot-houses, which are particularly numerous in that part of the town, and the drunken men whom he met continually, although it was a working day, completed the revolting misery of the picture. An expression of the profoundest disgust gleamed for a moment in the young man’s refined face. He was, by the way, exceptionally handsome, above the average in height, slim, well-built, with beautiful dark eyes and dark brown hair. Soon he sank into deep thought, or more accurately speaking into a complete blankness of mind; he walked along not observing what was about him and not caring to observe it. From time to time, he would mutter something, from the habit of talking to himself, to which he had just confessed. At these moments he would become conscious that his ideas were sometimes in a tangle and that he was very weak; for two days he had scarcely tasted food."}, {"id": 8, "para": 6, "quote": false, "text": "He was so badly dressed that even a man accustomed to shabbiness would have been ashamed to be seen in the street in such rags. In that quarter of the town, however, scarcely any shortcoming in dress would have created surprise. Owing to the proximity of the Hay Market, the number of establishments of bad character, the preponderance of the trading and working class population crowded in these streets and alleys in the heart of Petersburg, types so various were to be seen in the streets that no figure, however queer, would have caused surprise. But there was such accumulated bitterness and contempt in the young man’s heart, that, in spite of all the fastidiousness of youth, he minded his rags least of all in the street. It was a different matter when he met with acquaintances or with former fellow students, whom, indeed, he disliked meeting at any time. And yet when a drunken man who, for some unknown reason, was being taken somewhere in a huge waggon dragged by a heavy dray horse, suddenly shouted at him as he drove past:"}, {"id": 9, "para": 6, "quote": true, "text": "“Hey there, German hatter”", "label": {"speaker": "the young man", "kind": "speech", "emotion": "surprised", "intensity": "high"}, "wrong": true}, {"id": 10, "para": 6, "quote": false, "text": "bawling at the top of his voice and pointing at him--the young man stopped suddenly and clutched tremulously at his hat. It was a tall round hat from Zimmerman’s, but completely worn out, rusty with age, all torn and bespattered, brimless and bent on one side in a most unseemly fashion. Not shame, however, but quite another feeling akin to terror had overtaken him."}, {"id": 11, "para": 7, "quote": true, "text": "“I knew it,”", "label": {"speaker": "the young man", "kind": "thought", "emotion": "anxious", "intensity": "high"}, "wrong": false}, {"id": 12, "para": 7, "quote": false, "text": "he muttered in confusion,"}, {"id": 13, "para": 7, "quote": true, "text": "“I thought so! That’s the worst of all! Why, a stupid thing like this, the most trivial detail might spoil the whole plan. Yes, my hat is too noticeable.... It looks absurd and that makes it noticeable.... With my rags I ought to wear a cap, any sort of old pancake, but not this grotesque thing. Nobody wears such a hat, it would be noticed a mile off, it would be remembered.... What matters is that people would remember it, and that would give them a clue. For this business one should be as little conspicuous as possible.... Trifles, trifles are what matter! Why, it’s just such trifles that always ruin everything....”", "label": {"speaker": "the young man", "kind": "thought", "emotion": "anxious", "intensity": "high"}, "wrong": false}, {"id": 14, "para": 8, "quote": false, "text": "He had not far to go; he knew indeed how many steps it was from the gate of his lodging house: exactly seven hundred and thirty. He had counted them once when he had been lost in dreams. At the time he had put no faith in those dreams and was only tantalising himself by their hideous but daring recklessness. Now, a month later, he had begun to look upon them differently, and, in spite of the monologues in which he jeered at his own impotence and indecision, he had involuntarily come to regard this"}, {"id": 15, "para": 8, "quote": true, "text": "“hideous”", "label": {"speaker": "the young man", "kind": "thought", "emotion": "disgusted", "intensity": "medium"}, "wrong": false}, {"id": 16, "para": 8, "quote": false, "text": "dream as an exploit to be attempted, although he still did not realise this himself. He was positively going now for a"}, {"id": 17, "para": 8, "quote": true, "text": "“rehearsal”", "label": {"speaker": "the young man", "kind": "thought", "emotion": "excited", "intensity": "high"}, "wrong": false}, {"id": 18, "para": 8, "quote": false, "text": "of his project, and at every step his excitement grew more and more violent."}, {"id": 19, "para": 9, "quote": false, "text": "With a sinking heart and a nervous tremor, he went up to a huge house which on one side looked on to the canal, and on the other into the street. This house was let out in tiny tenements and was inhabited by working people of all kinds--tailors, locksmiths, cooks, Germans of sorts, girls picking up a living as best they could, petty clerks, etc. There was a continual coming and going through the two gates and in the two courtyards of the house. Three or four door-keepers were employed on the building. The young man was very glad to meet none of them, and at once slipped unnoticed through the door on the right, and up the staircase. It was a back staircase, dark and narrow, but he was familiar with it already, and knew his way, and he liked all these surroundings: in such darkness even the most inquisitive eyes were not to be dreaded."}, {"id": 20, "para": 10, "quote": true, "text": "“If I am so scared now, what would it be if it somehow came to pass that I were really going to do it?”", "label": {"speaker": "the young man", "kind": "thought", "emotion": "disgusted", "intensity": "low"}, "wrong": false}, {"id": 21, "para": 10, "quote": false, "text": "he could not help asking himself as he reached the fourth storey. There his progress was barred by some porters who were engaged in moving furniture out of a flat. He knew that the flat had been occupied by a German clerk in the civil service, and his family. This German was moving out then, and so the fourth floor on this staircase would be untenanted except by the old woman."}, {"id": 22, "para": 10, "quote": true, "text": "“That’s a good thing anyway,”", "label": {"speaker": "the young man", "kind": "thought", "emotion": "sad", "intensity": "low"}, "wrong": false}, {"id": 23, "para": 10, "quote": false, "text": "he thought to himself, as he rang the bell of the old woman’s flat. The bell gave a faint tinkle as though it were made of tin and not of copper. The little flats in such houses always have bells that ring like that. He had forgotten the note of that bell, and now its peculiar tinkle seemed to remind him of something and to bring it clearly before him.... He started, his nerves were terribly overstrained by now. In a little while, the door was opened a tiny crack: the old woman eyed her visitor with evident distrust through the crack, and nothing could be seen but her little eyes, glittering in the darkness. But, seeing a number of people on the landing, she grew bolder, and opened the door wide. The young man stepped into the dark entry, which was partitioned off from the tiny kitchen. The old woman stood facing him in silence and looking inquiringly at him. She was a diminutive, withered up old woman of sixty, with sharp malignant eyes and a sharp little nose. Her colourless, somewhat grizzled hair was thickly smeared with oil, and she wore no kerchief over it. Round her thin long neck, which looked like a hen’s leg, was knotted some sort of flannel rag, and, in spite of the heat, there hung flapping on her shoulders, a mangy fur cape, yellow with age. The old woman coughed and groaned at every instant. The young man must have looked at her with a rather peculiar expression, for a gleam of mistrust came into her eyes again."}], "narrator": {"person": "third", "character": ""}, "characters": [{"name": "the young man", "aliases": ["German hatter (referenced in shout)", "character", "my dear (implied in monologue)", "the most trivial detail (referenced in thought)", "he", "the visitor", "the old woman's visitor"], "gender": "male", "age": "young adult"}, {"name": "the old woman", "aliases": ["the old woman", "she", "her", "a diminutive, withered up old woman of sixty", "the German's family member (implied)", "the flat's tenant"], "gender": "female", "age": "elderly"}], "scenes": [{"first_paragraph": 1, "setting": "A hot, crowded street in Petersburg", "mood": "anxious"}, {"first_paragraph": 6, "setting": "A dark, narrow back staircase", "mood": "tense"}]}], "voices": {"default_narrator": "af_bella", "timbre_words": ["low", "high", "bright", "dark", "brisk", "measured", "warm", "soft", "gruff", "crisp"], "clip_text": "The house stood at the end of a long gravel road, behind a row of old chestnut trees. Every morning the post arrived at nine, and every evening the lamps were lit before the sun went down.", "voices": [{"id": "af_alloy", "language": "en", "gender": "female", "age": "adult", "accent": "American", "timbre": ["low", "dark", "measured"], "narrator_ok": false, "clips": {"neutral": "af_alloy.wav"}, "source": "Kokoro-82M voice af_alloy (Apache-2.0)"}, {"id": "af_aoede", "language": "en", "gender": "female", "age": "adult", "accent": "American", "timbre": ["dark"], "narrator_ok": true, "clips": {"neutral": "af_aoede.wav"}, "source": "Kokoro-82M voice af_aoede (Apache-2.0)"}, {"id": "af_bella", "language": "en", "gender": "female", "age": "adult", "accent": "American", "timbre": ["high", "measured"], "narrator_ok": true, "clips": {"neutral": "af_bella.wav"}, "source": "Kokoro-82M voice af_bella (Apache-2.0)"}, {"id": "af_heart", "language": "en", "gender": "female", "age": "adult", "accent": "American", "timbre": ["high"], "narrator_ok": false, "clips": {"neutral": "af_heart.wav"}, "source": "Kokoro-82M voice af_heart (Apache-2.0)"}, {"id": "af_kore", "language": "en", "gender": "female", "age": "adult", "accent": "American", "timbre": ["low", "dark", "measured"], "narrator_ok": false, "clips": {"neutral": "af_kore.wav"}, "source": "Kokoro-82M voice af_kore (Apache-2.0)"}, {"id": "bf_emma", "language": "en", "gender": "female", "age": "adult", "accent": "British", "timbre": ["bright"], "narrator_ok": true, "clips": {"neutral": "bf_emma.wav"}, "source": "Kokoro-82M voice bf_emma (Apache-2.0)"}, {"id": "am_eric", "language": "en", "gender": "male", "age": "adult", "accent": "American", "timbre": ["high", "dark", "measured"], "narrator_ok": false, "clips": {"neutral": "am_eric.wav"}, "source": "Kokoro-82M voice am_eric (Apache-2.0)"}, {"id": "am_fenrir", "language": "en", "gender": "male", "age": "young adult", "accent": "American", "timbre": ["high"], "narrator_ok": true, "clips": {"neutral": "am_fenrir.wav"}, "source": "Kokoro-82M voice am_fenrir (Apache-2.0)"}, {"id": "am_michael", "language": "en", "gender": "male", "age": "adult", "accent": "American", "timbre": ["bright", "measured"], "narrator_ok": true, "clips": {"neutral": "am_michael.wav"}, "source": "Kokoro-82M voice am_michael (Apache-2.0)"}, {"id": "bm_daniel", "language": "en", "gender": "male", "age": "adult", "accent": "British", "timbre": ["bright", "brisk"], "narrator_ok": false, "clips": {"neutral": "bm_daniel.wav"}, "source": "Kokoro-82M voice bm_daniel (Apache-2.0)"}, {"id": "bm_fable", "language": "en", "gender": "male", "age": "adult", "accent": "British", "timbre": ["low", "dark", "brisk"], "narrator_ok": false, "clips": {"neutral": "bm_fable.wav"}, "source": "Kokoro-82M voice bm_fable (Apache-2.0)"}, {"id": "bm_lewis", "language": "en", "gender": "male", "age": "adult", "accent": "British", "timbre": ["low"], "narrator_ok": false, "clips": {"neutral": "bm_lewis.wav"}, "source": "Kokoro-82M voice bm_lewis (Apache-2.0)"}]}};
